mapper.select:
select count(1)
from lab_reservation r
join lab_device d on d.id = r.device_id and d.del_flag = '0'
where r.del_flag = '0'


        and r.status = 'PENDING'
        and r.applicant_id <> #{userId}
        and coalesce(r.submitter_id, r.applicant_id) <> #{userId}

    and r.status in ('PENDING', 'APPROVED')

  and (
      r.applicant_id = #{userId}

          or 1 = 1

              or d.laboratory_id in

                  #{laboratoryId}



  )

select count(1)
from lab_usage_record u
join lab_device d on d.id = u.device_id and d.del_flag = '0'
where u.del_flag = '0' and u.returned_at is null
  and (
      u.user_id = #{userId}

          or 1 = 1

              or d.laboratory_id in

                  #{laboratoryId}



  )

select count(1)
from lab_repair_order repair
join lab_device d on d.id = repair.device_id and d.del_flag = '0'
where repair.del_flag = '0' and repair.status <> 'CLOSED'
  and (
      repair.reporter_id = #{userId} or repair.assignee_id = #{userId}

          or 1 = 1

              or d.laboratory_id in

                  #{laboratoryId}



  )

select count(1)
from lab_inspection_task task
where task.del_flag = '0' and task.status in ('PENDING', 'IN_PROGRESS')
  and (
      task.assignee_id = #{userId}

          or 1 = 1

              or task.laboratory_id in

                  #{laboratoryId}



  )

select count(1)
from lab_hazard hazard
left join lab_device d on hazard.target_type = 'DEVICE'
                      and d.id = hazard.target_id and d.del_flag = '0'
where hazard.del_flag = '0' and hazard.status <> 'CLOSED'
  and (
      hazard.owner_id = #{userId}

          or 1 = 1

              or (hazard.target_type = 'LABORATORY' and hazard.target_id in

                      #{laboratoryId}
                  )
              or (hazard.target_type = 'DEVICE' and d.laboratory_id in

                      #{laboratoryId}
                  )


  )

select r.status as code, count(1) as value
from lab_reservation r
join lab_device d on d.id = r.device_id and d.del_flag = '0'
where r.del_flag = '0'
  and r.start_time >= #{windowStart}
  and r.start_time < #{windowEnd}
  and (
      r.applicant_id = #{userId}

          or 1 = 1

              or d.laboratory_id in

                  #{laboratoryId}



  )
group by r.status
order by r.status

select coalesce(sum(greatest(timestampdiff(minute, greatest(u.checked_out_at, #{windowStart}), least(coalesce(u.returned_at, #{windowEnd}), #{windowEnd})), 0)), 0) from lab_usage_record u join lab_device d on d.id = u.device_id and d.del_flag = '0' where u.del_flag = '0' and u.checked_out_at < #{windowEnd} and (u.returned_at is null or u.returned_at > #{windowStart}) and ( u.user_id = #{userId}
or 1 = 1
or d.laboratory_id in
#{laboratoryId}
)

select repair.status as code, count(1) as value
from lab_repair_order repair
join lab_device d on d.id = repair.device_id and d.del_flag = '0'
where repair.del_flag = '0'
  and repair.create_time >= #{windowStart}
  and repair.create_time < #{windowEnd}
  and (
      repair.reporter_id = #{userId} or repair.assignee_id = #{userId}

          or 1 = 1

              or d.laboratory_id in

                  #{laboratoryId}



  )
group by repair.status
order by repair.status

select hazard.status as code, count(1) as value
from lab_hazard hazard
left join lab_device d on hazard.target_type = 'DEVICE'
                      and d.id = hazard.target_id and d.del_flag = '0'
where hazard.del_flag = '0'
  and hazard.create_time >= #{windowStart}
  and hazard.create_time < #{windowEnd}
  and (
      hazard.owner_id = #{userId}

          or 1 = 1

              or (hazard.target_type = 'LABORATORY' and hazard.target_id in

                      #{laboratoryId}
                  )
              or (hazard.target_type = 'DEVICE' and d.laboratory_id in

                      #{laboratoryId}
                  )


  )
group by hazard.status
order by hazard.status
